from __future__ import annotations
import unittest
from nexmind_god_mode.contracts import ContractViolation,validate_visual_candidate,validate_visual_output,validate_premium_selection_reasoning
from nexmind_god_mode.art_contracts import validate_art_candidate
from nexmind_god_mode.provider_schemas import VISUAL_SCHEMA,ART_SCHEMA,SHOWRUNNER_SELECTION_SCHEMA
from nexmind_god_mode.storyboard_compiler import StoryboardCompiler

class PremiumCreativeContracts(unittest.TestCase):
 def visual(self):
  return {'candidate_id':'V9','representation':'AUTHORED_ILLUSTRATION','visual_thesis':'A delivery package becomes the persistent proof of a broken-to-trusted workflow.','hero_kind':'delivery package','transformation':'uncertain handoffs become one visibly accountable delivery path','camera_idea':'stay with the package and move only when its responsibility changes','rationale':'The product promise is trust through continuity, so one persistent package makes accountability physical.',
   'concept_signature':{'brief_specific_hook':'the package is both the user request and the proof of delivery','governing_visual_logic':'every handoff leaves a visible state on the same package','emotional_engine':'uncertainty resolves into confidence','memorability_device':'the same marked package survives the whole film','transplant_test':'It would fail on an unrelated finance brief because the physical delivery handoff is the argument, not decoration.'},
   'rehearsal_states':[{'label':'dispatch uncertainty','state':'an unmarked package waits on a cluttered dispatch desk','purpose':'establish anonymous responsibility'},{'label':'owned handoff','state':'the same package crosses a clearly owned handoff','purpose':'make responsibility physical'},{'label':'route correction','state':'a failed route is visibly corrected without losing package identity','purpose':'prove continuity under stress'},{'label':'delivery trust','state':'the marked package arrives and closes the trust loop','purpose':'pay off persistent ownership'}],
   'originality_guard':{'reference_independence':'uses no reference layout or signature motif','template_risk':'low because the persistent delivery object and handoff logic are brief-derived','why_not_obvious':'it avoids the obvious app-screen/process-diagram explanation and makes accountability physical'},
   'beat_treatments':[{'beat_id':'B1','hero_state':'unmarked package','visual_action':'package receives a visible ownership mark','audience_takeaway':'the request now has an owner','supporting_elements':['dispatch desk','courier hand'],'world_state':'busy dispatch desk with one package isolated as the focal object','visual_consequence':'the package visibly changes from anonymous to owned','continuity_handoff':'ownership mark persists into the next beat'},{'beat_id':'B2','hero_state':'marked package delivered','visual_action':'package crosses the doorway into the recipient hand','audience_takeaway':'ownership becomes completed delivery','supporting_elements':['doorway','recipient hand'],'world_state':'clean recipient threshold resolving the earlier dispatch space','visual_consequence':'the same mark closes into a delivery seal','continuity_handoff':'delivery seal is the final payoff'}]}
 def art(self):
  return {'candidate_id':'A9','visual_candidate_id':'V9','art_thesis':'A tactile editorial delivery world with the package always visually dominant.',
   'art_bible':{'shape_language':'broad rounded architectural planes around a crisp rectangular package','line_edge_language':'confident dark outlines with selective soft edges in atmosphere','palette_relationship':'warm paper neutrals with one cobalt ownership accent','material_texture_language':'matte paper, soft painted walls and restrained grain','lighting_value_structure':'bright package face against quieter middle-value environments','depth_language':'foreground hands, midground package and contextual background architecture','environment_language':'lived-in dispatch and recipient spaces with only story-relevant operational evidence','prop_language':'specific working objects with visible use state, never generic icon substitutes','character_language':'cropped expressive hands/body fragments only where contact clarifies ownership','typography_relationship':'small editorial labels behave like printed marks within the world, never floating UI','continuity_rules':['the package silhouette and cobalt ownership mark never change','environment density escalates at uncertainty and resolves at delivery']},
   'hero':{'semantic_ref':'delivery package','art_budget':'HIGH','prominence':'DOMINANT','recognizable_required':True},
   'composition':{'archetype':'persistent-object spatial narrative','hierarchy_order':['package','contact hand','environment evidence'],'negative_space_intent':'protect the package face and delivery seal','density':'RICH','asymmetry_intent':'package sits off-center against directional operational context','foreground_strategy':'hands and threshold edges occasionally cross frame to create contact','midground_strategy':'package remains the stable ownership anchor','background_strategy':'contextual desk/door architecture explains place without becoming diagrammatic','scale_contrast_intent':'package grows from medium object to dominant payoff close-up','overlap_intent':'foreground contact overlaps the package only at causal handoffs','execution_directives':{'spatial_mode':'GROUNDED_SCENE','depth_mode':'DEEP','hero_scale':'DOMINANT_CLOSE','environment_density':'LIVED_IN','overlap_mode':'PURPOSEFUL_FOREGROUND','typography_mode':'EMBEDDED'},'support_budget':3,'decoration_budget':1},
   'form_request':{'concept':'delivery package in operational environments','representation':'AUTHORED_ILLUSTRATION','semantic_parts':['package','dispatch desk','courier hand','doorway'],'required_operations':['mark ownership','handoff','deliver'],'style':'tactile editorial illustration'},
   'beat_art':[{'beat_id':'B1','settled_visual_state':'marked package sits dominant on a lived-in dispatch desk after ownership is assigned','focal_owner':'delivery package','supporting_roles':['dispatch desk','courier hand'],'environment_state':'operational dispatch desk with clipped paperwork, shelf depth and route evidence','prop_specificity':'tape seam, printed ownership mark, used clipboard and dispatch label','character_performance_state':'courier hand has just released after marking; wrist posture reads deliberate responsibility','typography_role':'ownership mark is embedded on the package; no floating headline competes','depth_read':'foreground hand edge, midground package, background shelf/desk world','meaning_without_motion':True},{'beat_id':'B2','settled_visual_state':'same marked package crosses the recipient doorway and lands in a receiving hand','focal_owner':'delivery package','supporting_roles':['doorway','recipient hand'],'environment_state':'recipient threshold with clear interior/exterior depth and restrained home evidence','prop_specificity':'same tape seam and ownership mark plus final delivery seal','character_performance_state':'recipient hand supports weight while courier hand exits, making transfer legible','typography_role':'delivery seal is the only text-like mark and functions as payoff evidence','depth_read':'foreground threshold edge, midground package/hands, quiet interior background','meaning_without_motion':True}],
   'typography_intent':'embedded evidence marks only','risk_notes':['avoid turning the delivery route into a flowchart']}
 def test_live_schemas_require_premium_fields(self):
  vreq=set(VISUAL_SCHEMA['properties']['candidates']['items']['required']);self.assertTrue({'concept_signature','rehearsal_states','originality_guard'}<=vreq)
  areq=set(ART_SCHEMA['properties']['candidates']['items']['required']);self.assertIn('art_bible',areq); self.assertIn('execution_directives',ART_SCHEMA['properties']['candidates']['items']['properties']['composition']['required'])
  sreq=set(SHOWRUNNER_SELECTION_SCHEMA['required']);self.assertTrue({'decision_basis','brief_specific_evidence','strongest_alternative_id','why_strongest_alternative_loses','selection_risk'}<=sreq)
 def test_premium_visual_contract(self): self.assertEqual(validate_visual_candidate(self.visual(),{'B1','B2'})['candidate_id'],'V9')
 def test_premium_visual_partial_contract_rejected(self):
  v=self.visual();v.pop('originality_guard')
  with self.assertRaises(ContractViolation):validate_visual_candidate(v,{'B1','B2'})
 def test_premium_visual_candidate_set_rejects_duplicate_theses(self):
  import copy
  a=self.visual();b=copy.deepcopy(a);c=copy.deepcopy(a)
  a['candidate_id']='V1';b['candidate_id']='V2';c['candidate_id']='V3'
  with self.assertRaisesRegex(ContractViolation,'duplicate creative thesis|material diversity|semantic/structural novelty'):
   validate_visual_output({'candidates':[a,b,c]},{'B1','B2'})
 def test_premium_art_contract(self): self.assertEqual(validate_art_candidate(self.art(),{'B1','B2'},'V9')['candidate_id'],'A9')
 def test_premium_art_partial_beat_rejected(self):
  a=self.art();a['beat_art'][0].pop('environment_state')
  with self.assertRaises(ContractViolation):validate_art_candidate(a,{'B1','B2'},'V9')
 def test_selection_requires_specific_reasoning_when_premium_fields_present(self):
  p={'selected_candidate_id':'V9','why':'specific','tradeoffs':[],'rejected_alternatives':[{'candidate_id':'V8','reason':'less specific'}],'decision_basis':{'brief_specific_fit':'package handoff matches the brief','creative_distinctiveness':'persistent marked object','audience_effect':'uncertainty resolves into trust','commercial_finish':'supports authored tactile frames','capability_fit':'uses supported object/environment bodies'},'brief_specific_evidence':['ownership mark persists','delivery threshold pays off dispatch setup'],'strongest_alternative_id':'V8','why_strongest_alternative_loses':'it explains the workflow but lacks the physical trust payoff','selection_risk':'package art must remain visually premium'}
  validate_premium_selection_reasoning(p,{'V8','V9'})
 def test_storyboard_carries_art_and_visual_bible(self):
  story={'film_thesis':{'central_argument':'trust follows continuity'},'beats':[{'beat_id':'B1','purpose':'establish','reveal':'ownership','audience_before':'uncertain','audience_after':'understands ownership','narration_mode':'SILENT','narration_text':'','narration_purpose':''},{'beat_id':'B2','purpose':'payoff','reveal':'delivery','audience_before':'understands ownership','audience_after':'trusts delivery','narration_mode':'SILENT','narration_text':'','narration_purpose':''}]}
  board=StoryboardCompiler().compile(story,self.visual(),self.art(),{'status':'SUPPORTED'})
  self.assertEqual(board['beats'][0]['visual_direction']['concept_signature']['brief_specific_hook'],self.visual()['concept_signature']['brief_specific_hook'])
  self.assertEqual(board['beats'][0]['art_direction']['art_bible']['shape_language'],self.art()['art_bible']['shape_language'])
  self.assertIn('environment_state',board['beats'][0]['art_direction'])
if __name__=='__main__':unittest.main()
